function readWithRetry(op, attempts, done) {          // Node-style error-first callback
  (function tryOnce(n) {
    op((err, result) => {
      if (!err) return done(null, result);
      if (n === 0) return done(err);
      setImmediate(() => tryOnce(n - 1));                // never call back inline
    });
  })(attempts);
}

const onTick = () => console.log(Date.now());
process.on('SIGINT', onTick);                            // registration by identity
process.off('SIGINT', onTick);                           // same reference to remove
